package com.hmdp.ai.infrastructure.sandbox;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.hmdp.ai.domain.artifact.ArtifactReference;import com.hmdp.ai.domain.run.ExecutionContext;import org.springframework.stereotype.Component;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Path;import java.util.*;import java.util.concurrent.TimeUnit;
@Component public class DockerSandboxExecutor implements SandboxExecutor {private final ObjectMapper mapper;private final SandboxFileService files;private final SandboxArtifactService artifacts;public DockerSandboxExecutor(ObjectMapper mapper,SandboxFileService files,SandboxArtifactService artifacts){this.mapper=mapper;this.files=files;this.artifacts=artifacts;}
    public SandboxExecution execute(Path workspace,JsonNode c,JsonNode input,ExecutionContext context,int timeoutMs){try{String command=input.path("command").asText();Set<String>allowed=new LinkedHashSet<>();c.path("allowedCommands").forEach(v->allowed.add(v.asText()));if(command.isEmpty()||!allowed.contains(command))throw new IllegalArgumentException("SANDBOX_COMMAND_NOT_ALLOWED");String image=c.path("image").asText();if(!image.matches("[A-Za-z0-9._/:@-]{1,200}"))throw new IllegalArgumentException("SANDBOX_IMAGE_INVALID");int maxInput=Math.max(1024,c.path("maxInputBytes").asInt(1024*1024));if(input.path("files").isObject())input.path("files").fields().forEachRemaining(e->files.write(workspace,e.getKey(),e.getValue().asText(),maxInput));List<String>cmd=new ArrayList<>(Arrays.asList("docker","run","--rm","--network","none","--cpus",String.valueOf(Math.max(0.1,c.path("cpus").asDouble(1.0))),"--memory",Math.max(64,c.path("memoryMb").asInt(256))+"m","--pids-limit",String.valueOf(Math.max(16,c.path("pidsLimit").asInt(64))),"-v",workspace.toString()+":/workspace:rw","-w","/workspace",image,command));if(input.path("args").isArray())for(JsonNode arg:input.path("args")){String v=arg.asText();if(v.length()>256||v.matches(".*[\\r\\n\\0].*"))throw new IllegalArgumentException("SANDBOX_ARGUMENT_INVALID");cmd.add(v);}Process process=new ProcessBuilder(cmd).redirectErrorStream(true).start();boolean done=process.waitFor(timeoutMs,TimeUnit.MILLISECONDS);if(!done){process.destroyForcibly();throw new IllegalStateException("SANDBOX_TIMEOUT");}String output=read(process.getInputStream(),Math.max(1024,c.path("maxOutputBytes").asInt(1024*1024)));ObjectNode data=mapper.createObjectNode().put("exitCode",process.exitValue()).put("output",output);List<ArtifactReference>refs=artifacts.store(context,workspace,context.getExecutionBudget().getMaxArtifactBytes());return new SandboxExecution(data,refs);}catch(IllegalArgumentException e){throw e;}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("SANDBOX_EXECUTION_FAILED",e);}}
    private String read(InputStream in,int max)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[]b=new byte[4096];int n,total=0;while((n=input.read(b))>=0){total+=n;if(total>max)throw new IllegalArgumentException("SANDBOX_OUTPUT_TOO_LARGE");out.write(b,0,n);}return out.toString(StandardCharsets.UTF_8.name());}}}
